head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25200";
scwin.delay = false;
scwin.result = null;
scwin.checkIsBeforePW = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — sType, sMessage

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.checkIsBeforePW = scwin.tx_checkIsBeforePW;
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25200.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "ipt_fssUnqNo", fn: function () { return String(String((dma_pageContext.get("fssUnqNo") ?? ""))); } },
        { childId: "ipt_comNm", fn: function () { return String(String((dma_pageContext.get("comNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.checkResult();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description btn_Save 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25200.btn_Save_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Save
 * @description Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Save = async function () {
    const sbmOptions = {
        id: "tx_fn_Save",
        method: "post",
        action: "/account/password.do?method=updatePassword",
        ref: "dma_SaveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_checkIsBeforePW
 * @description check Is Before PW 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_checkIsBeforePW = async function () {
    const sbmOptions = {
        id: "tx_checkIsBeforePW",
        method: "post",
        action: "/main/login.do?method=isBeforePw",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_checkSafety
 * @description check Safety 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_checkSafety = async function () {
    const sbmOptions = {
        id: "tx_checkSafety",
        method: "post",
        action: "/common/checkSafety.do?method=checkPWSafety",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkResult
 * @description check Result 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkResult = async function () {
    const tp = (String(((dma_pageContext.get("sType") ?? "")) == null ? '' : ((dma_pageContext.get("sType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sType") ?? "")) == null ? '' : ((dma_pageContext.get("sType") ?? ""))));
    if (tp === '1') {
        await $c.win.alert('비밀번호 수정을 완료하였습니다.');
    } else {
        if (tp === '2') {
            await $c.win.alert((String(((dma_pageContext.get("sMessage") ?? "")) == null ? '' : ((dma_pageContext.get("sMessage") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sMessage") ?? "")) == null ? '' : ((dma_pageContext.get("sMessage") ?? "")))));
        }
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    const frm = (document.passwordForm || { elements: [] });
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_pwChgConfrmVal'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_pw'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_pwChk'))) {
        return;
    }
    if ($c.util.getComponent('ipt_pw').getValue()!== $c.util.getComponent('ipt_pwChk').getValue()) {
        await $c.win.alert('입력한 새 비밀번호가 일치하지 않습니다. 새 비밀번호를 확인하십시오.');
        return;
    }
    if (!await scwin.checkPassword($c.util.getComponent('ipt_pw').getValue())) {
        pw.focus();
        return;
    }
    if ($c.util.getComponent('ipt_isPass').getValue() !== "Y") {
        await $c.win.alert("보안등급이 낮습니다. 비밀번호를 다시 입력해주십시오.");
        return;
    }
    if ($c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'Y') {
        $c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'N';
    }
    frm.action = '/account/password.do?method=updatePassword';
    await scwin.tx_fn_Save();
};

/**
 * @method
 * @name checkPassword
 * @description check Password 처리
 * @param {*} _password _password
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPassword = async function (_password) {
    const pwVal = _password;
    if (pwVal.length < 9) {
        await $c.win.alert("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        return false;
    }
    const strChk = /^[\a-z0-9_!@#^&*()]{8,}$/;
    if (!(strChk.test(pwVal.toLowerCase()))) {
        await $c.win.alert("변경 비밀번호는 한글,띄어쓰기는 사용하실 수 없습니다.\n_!@#^&*() 이외의 특수문자는 사용하실 수 없습니다.");
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const sChar_t = "_!@#^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let numberCheck_t = false;
    for (let i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) !== -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) !== -1) {
            alphaCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) !== -1) {
            numberCheck_t = true;
        }
    }
    if (sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) {
        await $c.win.alert("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        return false;
    }
    let sameCount = 1;
    let isCont = true;
    for (let i = 0; i < pwVal.length - 1; i++) {
        const currentChar = pwVal.charAt(i);
        const nextChar = pwVal.charAt(i + 1);
        const currentCharNum = parseInt(currentChar.charCodeAt(0));
        const continueCharNum = parseInt(nextChar.charCodeAt(0));
        if (currentChar === nextChar) {
            sameCount = sameCount + 1;
            if (sameCount >= 3) {
                break;
            }
        } else {
            sameCount = 1;
        }
        if (!(isCont && currentCharNum === continueCharNum - 1)) {
            isCont = false;
        }
    }
    if (sameCount >= 3) {
        await $c.win.alert('동일한 문자 또는 숫자가 3자 이상로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }
    if (isCont) {
        await $c.win.alert('주기성 문자(abcd, 1234 등)로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await $c.win.alert('변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.');
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (let i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length === 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await $c.win.alert('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name fnDelayKeyup
 * @description fn Delay Keyup 처리
 * @param {*} newPw newPw
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDelayKeyup = async function (newPw) {
    if (newPw.length > 0) {
        if (await scwin.checkPassword(newPw)) {
            if (!scwin.delay) {
                scwin.delay = true;
                self.setTimeout(function() {
                        scwin.checkIsBeforePW();
                    }, 1000);
            }
        }
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkSafety_done
 * @description check Safety done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.checkSafety_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_isPass').setValue(scwin.result.isPass);
    $c.util.getComponent('ipt_selfLevel').setValue(scwin.result.selfLevel);
    $c.util.getComponent('txt_msgLevel').setLabel(scwin.result.msgLevel);
    if (scwin.result.msgInfomation !== "") {
        $c.util.getComponent('txt_msgInfomation').setLabel("");
        // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
        $("#txt_msgInfomation").append(scwin.result.msgInfomation);
    } else {
        $c.util.getComponent('txt_msgInfomation').setLabel("");
    }
};

/**
 * @method
 * @name checkSafety
 * @description check Safety 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSafety = async function () {
    const r = await scwin.tx_checkSafety();
    try {
        scwin.checkSafety_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil25200.checkSafety' });
    }
    return r;
};
